async Task StopSessionAsync(Session session)
{
    if (!session.TryBeginStopping()) return;
    session.StopAcceptingNewWork();
    await session.WaitForCallbacksAsync();
    session.UnsubscribeOwnedHandlers();
    session.DisconnectOwnedEdges();
    session.StopOwnedMedia();
    session.DisposeOwnedMedia();
    session.MarkStopped();
}

